import asyncio
import os
import socket
import time

from .connector import Connector

whichever_timeout = (asyncio.TimeoutError, socket.timeout, TimeoutError)


class NetworkConnector(Connector):
    def __init__(self, port, baudrate=115200):
        self._host, port = port.split(":")
        super().__init__(port, baudrate)
        self._reader = None
        self._writer = None
        self._loop = self._create_new_eventloop()

    def open(self, timeout=None):
        try:
            self._reader, self._writer = self._loop.run_until_complete(
                asyncio.wait_for(asyncio.open_connection(host=self._host, port=int(self.port)), timeout=timeout)
            )

            sock = self._writer.get_extra_info("socket")
            if sock is None:
                raise ConnectionRefusedError("Cannot access underlying socket connection")
            if os.name == "nt":
                sock.ioctl(socket.SIO_KEEPALIVE_VALS, (1, 100, 100))
            else:
                sock.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 5)
                sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPIDLE, 1)
                sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPINTVL, 1)
                sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPCNT, 3)
                sock.setsockopt(socket.SOL_TCP, socket.TCP_NODELAY, 1)

        except (ConnectionRefusedError, OSError) as e:
            raise ConnectionRefusedError(
                f"Could not open tcp connection on {self._host}:{self.port} due to {e.__class__.__name__}: {e}"
            )
        except whichever_timeout:
            raise ConnectionRefusedError("Timeout reached")

    def close(self, timeout=30):
        if self._writer:
            self._writer.close()
            t = time.monotonic() + timeout
            while self._loop.is_running() and time.monotonic() < t:
                time.sleep(0.5)
            try:
                self._loop.run_until_complete(self._writer.wait_closed())
            except whichever_timeout:
                pass
            except RuntimeError:
                pass
            self._writer = None

    def is_closed(self):
        if self._writer_connection_closed_precheck():
            return True
        try:
            return self._check_socket_is_closed()
        except BlockingIOError:
            return False
        except whichever_timeout:
            return False
        except (ConnectionResetError, ConnectionError, OSError):
            return True

    def _writer_connection_closed_precheck(self):
        if not self._writer or not self._reader:
            return True
        if self._writer.is_closing() or self._reader.at_eof():
            return True
        return False

    def _check_socket_is_closed(self):
        sock = self._writer.get_extra_info("socket")
        if sock is None:
            return True
        data = self._loop.run_until_complete(asyncio.wait_for(self._reader.read(), self._readline_timeout))
        if len(data) == 0:
            return True
        else:
            self._reader.feed_data(data)
        return False

    def in_waiting(self):
        return len(self._reader._buffer)

    def send_break(self):
        raise NotImplementedError("ETH connector; Sending BREAK is not supported.")

    def _read_one_line(self):
        try:
            data = self._loop.run_until_complete(
                asyncio.wait_for(self._reader.readuntil(b"\r"), self._readline_timeout)
            )
        except whichever_timeout:
            try:
                data = self._loop.run_until_complete(
                    asyncio.wait_for(self._reader.readexactly(self.in_waiting()), self._readline_timeout)
                )
            except whichever_timeout:
                return ""
        if isinstance(data, bytes):
            return data.decode("ascii", errors="backslashreplace")
        return data

    def read_available(self):
        try:
            data = self._loop.run_until_complete(
                asyncio.wait_for(self._reader.read(4096), timeout=0.001)
            )
            if data:
                return data.decode("ascii", errors='backslashreplace')
        except whichever_timeout:
            pass
        return ""

    def _send(self, cmd):
        cmd = cmd.encode(encoding="ascii", errors="backslashreplace")
        self._writer.write(cmd)
        self._loop.run_until_complete(self._writer.drain())

    @staticmethod
    def _create_new_eventloop():
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        return asyncio.get_event_loop()
